import torch
import torch.nn as nn

class MLP(nn.Module):
    def __init__(self, dims, activation=nn.Sigmoid):
        super().__init__()
        layers = []
        for i in range(len(dims) - 1):
            layers.append(nn.Linear(dims[i], dims[i+1]))
            if i < len(dims) - 2:
                layers.append(activation())
        self.net = nn.Sequential(*layers)

    def forward(self, x):
        return self.net(x)

torch.manual_seed(0)
model_sig  = MLP([16, 64, 64, 64, 1], activation=nn.Sigmoid)
model_relu = MLP([16, 64, 64, 64, 1], activation=nn.ReLU)

x = torch.randn(32, 16)
y = torch.zeros(32, 1)

for name, model in [('Sigmoid', model_sig), ('ReLU', model_relu)]:
    loss = nn.MSELoss()(model(x), y)
    loss.backward()
    print('Gradient norms per Linear layer (%s):' % name)
    linear_idx = 0
    for layer in model.net:
        if isinstance(layer, nn.Linear) and layer.weight.grad is not None:
            gnorm = layer.weight.grad.norm().item()
            print('  Layer %d: %.2e' % (linear_idx, gnorm))
            linear_idx += 1
    model.zero_grad()
    print('')

import math

class Dual:
    # Dual number: val + eps * deriv  (eps^2 = 0)
    def __init__(self, val, deriv=0.0):
        self.val   = val
        self.deriv = deriv

    def __add__(self, other):
        if isinstance(other, Dual):
            return Dual(self.val + other.val, self.deriv + other.deriv)
        return Dual(self.val + other, self.deriv)

    def __radd__(self, other):
        return self.__add__(other)

    def __mul__(self, other):
        if isinstance(other, Dual):
            # product rule: (u*v)' = u'v + uv'
            return Dual(self.val * other.val,
                        self.val * other.deriv + self.deriv * other.val)
        return Dual(self.val * other, self.deriv * other)

    def __repr__(self):
        return 'Dual(%.6f + eps*%.6f)' % (self.val, self.deriv)

def sin_d(x):  return Dual(math.sin(x.val), x.deriv * math.cos(x.val))
def exp_d(x):  return Dual(math.exp(x.val), x.deriv * math.exp(x.val))

# f(x) = x^2 * sin(x) + exp(x)  at x=1.5
x = Dual(1.5, 1.0)    # seed deriv=1 to get df/dx
y = x * x * sin_d(x) + exp_d(x)
print('f(1.5)               =', round(y.val,   6))
print('f prime(1.5) [dual]  =', round(y.deriv, 6))

# Analytical: f'(x) = 2x*sin(x) + x^2*cos(x) + exp(x)
xv = 1.5
ana = 2*xv*math.sin(xv) + xv**2*math.cos(xv) + math.exp(xv)
print('f prime(1.5) [exact] =', round(ana, 6))
print('Error:', abs(y.deriv - ana))

import torch
import torch.nn as nn
from torch.utils.checkpoint import checkpoint

class TransformerBlock(nn.Module):
    def __init__(self, d):
        super().__init__()
        self.fc1 = nn.Linear(d, d * 4)
        self.act = nn.GELU()
        self.fc2 = nn.Linear(d * 4, d)
        self.ln  = nn.LayerNorm(d)

    def forward(self, x):
        return self.ln(x + self.fc2(self.act(self.fc1(x))))

class DeepNet(nn.Module):
    def __init__(self, d, n_layers, use_checkpoint=False):
        super().__init__()
        self.blocks = nn.ModuleList([TransformerBlock(d) for _ in range(n_layers)])
        self.use_ckpt = use_checkpoint

    def forward(self, x):
        for blk in self.blocks:
            x = checkpoint(blk, x, use_reentrant=False) if self.use_ckpt else blk(x)
        return x

d, n_layers = 128, 8
x = torch.randn(4, d)

for name, use_ckpt in [('Normal', False), ('Checkpointed', True)]:
    model = DeepNet(d, n_layers, use_checkpoint=use_ckpt)
    out   = model(x).sum()
    out.backward()
    print('%s backward: gradients OK' % name)

print('Checkpointing: recomputes activations in backward pass.')
print('Memory: O(n_layers) -> O(sqrt(n_layers)) with segment checkpointing.')

import numpy as np
import math

def cosine_anneal(step, T, eta_max=1e-3, eta_min=1e-6):
    # eta(t) = eta_min + (eta_max - eta_min)/2 * (1 + cos(pi*t/T))
    return eta_min + (eta_max - eta_min) * 0.5 * (1.0 + math.cos(math.pi * step / T))

def warmup_cosine(step, warmup, total, eta_max=1e-3, eta_min=1e-6):
    # Phase 1: linear warmup  [0, warmup)
    # Phase 2: cosine decay   [warmup, total]
    if step < warmup:
        return eta_max * step / max(warmup, 1)
    progress = (step - warmup) / max(total - warmup, 1)
    return eta_min + (eta_max - eta_min) * 0.5 * (1.0 + math.cos(math.pi * progress))

total, warmup = 1000, 100

print('Warmup + cosine annealing schedule:')
print('%-6s  %-12s  %s' % ('Step', 'LR', 'Bar'))
for t in [0, 25, 50, 100, 200, 400, 600, 800, 999]:
    lr  = warmup_cosine(t, warmup, total)
    bar = '#' * int(lr / 1e-3 * 30)
    print('%6d  %.4e    %s' % (t, lr, bar))

lrs = [warmup_cosine(t, warmup, total) for t in range(total)]
print('')
print('Peak LR: %.2e  |  Final LR: %.2e' % (max(lrs), lrs[-1]))
print('Warmup: %d steps  |  Cosine decay: %d steps' % (warmup, total - warmup))

import math

def wsd_schedule(step, T_w, T_s, T_d, eta_max, eta_min=0.0):
    # Warmup-Stable-Decay (WSD) schedule
    # Phase 1 [0, T_w):          linear warmup
    # Phase 2 [T_w, T_w+T_s):   stable (constant at eta_max)
    # Phase 3 [T_w+T_s, total): cosine decay to eta_min
    if step < T_w:
        return eta_max * step / max(T_w, 1)
    elif step < T_w + T_s:
        return eta_max
    else:
        t = step - T_w - T_s
        return eta_min + (eta_max - eta_min) * 0.5 * (1 + math.cos(math.pi * t / max(T_d, 1)))

# Typical LLM pretraining budget: 100k steps
T_w, T_s, T_d = 1000, 89000, 10000
eta_max = 3e-4
eta_min = 3e-5
T_total = T_w + T_s + T_d

print('WSD schedule (%d total steps):' % T_total)
print('  Warmup: %d  Stable: %d  Decay: %d' % (T_w, T_s, T_d))
print('')
print('%-10s %-12s %s' % ('Step', 'LR', 'Phase'))
for step in [0, 500, 1000, 5000, 50000, 89000, 90000, 95000, 99999]:
    if step < T_total:
        lr = wsd_schedule(step, T_w, T_s, T_d, eta_max, eta_min)
        if step < T_w:
            phase = 'warmup'
        elif step < T_w + T_s:
            phase = 'stable'
        else:
            phase = 'decay'
        print('%-10d %-12.2e %s' % (step, lr, phase))
print('')
print('Most compute budget in stable phase; decay delivers final convergence.')
